import { type SocketState } from "@hunt/socket-manager";
import { exposeLocalStateTools, localDatasetManager } from "./local_state";

function handleConnectionStateChange(state: SocketState) {
  document.dispatchEvent(
    new CustomEvent("hunt:socketStateChange", { detail: state }),
  );
  (
    window as unknown as { huntConnectionState: SocketState }
  ).huntConnectionState = state;
}

if (typeof window !== "undefined") {
  // Local-only mode: treat as connected for UI that depends on socket state.
  handleConnectionStateChange("connected");
  exposeLocalStateTools();
}

export default localDatasetManager;
