import { genId } from "@hunt/gen-id";
import { actionForDataset } from "@hunt/socket-manager";
import { openDB, type IDBPDatabase } from "idb";
import {
  type Dataset,
  type DatasetParams,
  type DatasetValue,
  type ObjectWithEpoch,
  type ObjectWithId,
} from "../../../lib/api/websocket";

const LOCAL_STATE_VERSION = 1;
const STORAGE_PREFIX = "hunt.localState.dataset:";
const VERSION_KEY = "hunt.localState.version";

type LocalStateExport = {
  version: number;
  exportedAt: string;
  datasets: Record<string, DatasetValue>;
};

type Watcher = {
  id: string;
  callback: (value: object) => void;
};

type SubscriptionState = {
  datasetKey: string;
  dataset: Dataset;
  params: DatasetParams;
  action: "replace" | "append";
  lastValue: DatasetValue;
  initialValue: DatasetValue;
  watchers: Watcher[];
  loadPromise?: Promise<void>;
};

type StorageAdapter = {
  getItem: (key: string) => Promise<string | null>;
  setItem: (key: string, value: string) => Promise<void>;
  removeItem: (key: string) => Promise<void>;
  clear: (prefix?: string) => Promise<void>;
  keys: () => Promise<string[]>;
};

const safeJsonParse = (value: string | null): unknown => {
  if (!value) return undefined;
  try {
    return JSON.parse(value) as unknown;
  } catch {
    return undefined;
  }
};

const stringifyParams = (params: DatasetParams): string => {
  const encoded = JSON.stringify(params);
  return encoded;
};

const buildDatasetKey = (dataset: Dataset, params: DatasetParams): string =>
  `${dataset}:${stringifyParams(params)}`;

const storageKeyForDatasetKey = (datasetKey: string): string =>
  `${STORAGE_PREFIX}${datasetKey}`;

const parseDatasetKey = (
  datasetKey: string,
): { dataset: Dataset; params: DatasetParams } | undefined => {
  const separatorIndex = datasetKey.indexOf(":");
  if (separatorIndex === -1) return undefined;
  const dataset = datasetKey.slice(0, separatorIndex) as Dataset;
  const paramsRaw = datasetKey.slice(separatorIndex + 1);
  const params =
    paramsRaw === "undefined"
      ? undefined
      : (safeJsonParse(paramsRaw) as DatasetParams | undefined);
  return { dataset, params };
};

const storageTypeForDataset = (dataset: Dataset): "local" | "indexedDb" =>
  actionForDataset(dataset) === "append" ? "indexedDb" : "local";

class MemoryStorage implements StorageAdapter {
  private store = new Map<string, string>();

  getItem(key: string) {
    return Promise.resolve(this.store.get(key) ?? null);
  }

  setItem(key: string, value: string) {
    this.store.set(key, value);
    return Promise.resolve();
  }

  removeItem(key: string) {
    this.store.delete(key);
    return Promise.resolve();
  }

  clear(prefix?: string) {
    if (!prefix) {
      this.store.clear();
      return Promise.resolve();
    }
    for (const key of this.store.keys()) {
      if (key.startsWith(prefix)) {
        this.store.delete(key);
      }
    }
    return Promise.resolve();
  }

  keys() {
    return Promise.resolve(Array.from(this.store.keys()));
  }
}

class LocalStorageAdapter implements StorageAdapter {
  private storage: Storage | null;

  constructor() {
    if (typeof window === "undefined") {
      this.storage = null;
    } else {
      try {
        this.storage = window.localStorage;
      } catch {
        this.storage = null;
      }
    }
  }

  getItem(key: string) {
    if (!this.storage) return Promise.resolve(null);
    try {
      return Promise.resolve(this.storage.getItem(key));
    } catch {
      return Promise.resolve(null);
    }
  }

  setItem(key: string, value: string) {
    if (!this.storage) return Promise.resolve();
    try {
      this.storage.setItem(key, value);
    } catch {
      // Ignore storage failures (private mode, quota, etc).
    }
    return Promise.resolve();
  }

  removeItem(key: string) {
    if (!this.storage) return Promise.resolve();
    try {
      this.storage.removeItem(key);
    } catch {
      // Ignore storage failures.
    }
    return Promise.resolve();
  }

  clear(prefix?: string) {
    if (!this.storage) return Promise.resolve();
    try {
      if (!prefix) {
        this.storage.clear();
        return Promise.resolve();
      }
      const keys = Object.keys(this.storage);
      keys.forEach((key) => {
        if (key.startsWith(prefix)) {
          this.storage?.removeItem(key);
        }
      });
    } catch {
      // Ignore storage failures.
    }
    return Promise.resolve();
  }

  keys() {
    if (!this.storage) return Promise.resolve([]);
    return Promise.resolve(Object.keys(this.storage));
  }
}

type LocalStateDb = {
  datasets: {
    key: string;
    value: string;
  };
};

class IndexedDbAdapter implements StorageAdapter {
  private dbPromise: Promise<IDBPDatabase<LocalStateDb>> | null = null;
  private fallback = new MemoryStorage();

  private async openDb() {
    if (!this.dbPromise) {
      this.dbPromise = openDB<LocalStateDb>("hunt_local_state", 1, {
        upgrade(db) {
          if (!db.objectStoreNames.contains("datasets")) {
            db.createObjectStore("datasets");
          }
        },
      });
    }
    return this.dbPromise;
  }

  async getItem(key: string) {
    if (typeof window === "undefined") {
      return this.fallback.getItem(key);
    }
    try {
      const db = await this.openDb();
      const value = await db.get("datasets", key);
      return value ?? null;
    } catch {
      return this.fallback.getItem(key);
    }
  }

  async setItem(key: string, value: string) {
    if (typeof window === "undefined") {
      await this.fallback.setItem(key, value);
      return;
    }
    try {
      const db = await this.openDb();
      await db.put("datasets", value, key);
    } catch {
      await this.fallback.setItem(key, value);
    }
  }

  async removeItem(key: string) {
    if (typeof window === "undefined") {
      await this.fallback.removeItem(key);
      return;
    }
    try {
      const db = await this.openDb();
      await db.delete("datasets", key);
    } catch {
      await this.fallback.removeItem(key);
    }
  }

  async clear(prefix?: string) {
    if (typeof window === "undefined") {
      await this.fallback.clear(prefix);
      return;
    }
    try {
      const db = await this.openDb();
      if (!prefix) {
        await db.clear("datasets");
        return;
      }
      const tx = db.transaction("datasets", "readwrite");
      let cursor = await tx.store.openCursor();
      while (cursor) {
        if (typeof cursor.key === "string" && cursor.key.startsWith(prefix)) {
          await cursor.delete();
        }
        cursor = await cursor.continue();
      }
      await tx.done;
    } catch {
      await this.fallback.clear(prefix);
    }
  }

  async keys() {
    if (typeof window === "undefined") {
      return this.fallback.keys();
    }
    try {
      const db = await this.openDb();
      const keys = await db.getAllKeys("datasets");
      return keys;
    } catch {
      return this.fallback.keys();
    }
  }
}

class LocalDatasetManager {
  private localStorageAdapter = new LocalStorageAdapter();
  private indexedDbAdapter = new IndexedDbAdapter();
  private subsByDataset = new Map<string, SubscriptionState>();
  private migrationPromise: Promise<void> | null = null;

  private ensureVersion = async () => {
    const rawVersion = await this.localStorageAdapter.getItem(VERSION_KEY);
    const parsed = rawVersion ? Number.parseInt(rawVersion, 10) : NaN;
    if (!Number.isNaN(parsed) && parsed === LOCAL_STATE_VERSION) {
      return;
    }
    await this.clearStoredDatasets();
    await this.localStorageAdapter.setItem(
      VERSION_KEY,
      String(LOCAL_STATE_VERSION),
    );
  };

  private maybeMigrate() {
    if (!this.migrationPromise) {
      this.migrationPromise = this.ensureVersion();
    }
    return this.migrationPromise;
  }

  private storageAdapterForDataset(dataset: Dataset): StorageAdapter {
    return storageTypeForDataset(dataset) === "indexedDb"
      ? this.indexedDbAdapter
      : this.localStorageAdapter;
  }

  private async clearStoredDatasets() {
    await this.localStorageAdapter.clear(STORAGE_PREFIX);
    await this.indexedDbAdapter.clear(STORAGE_PREFIX);
  }

  private async loadStoredValue(
    sub: SubscriptionState,
  ): Promise<DatasetValue | undefined> {
    await this.maybeMigrate();
    const key = storageKeyForDatasetKey(sub.datasetKey);
    const adapter = this.storageAdapterForDataset(sub.dataset);
    const stored = await adapter.getItem(key);
    const parsed = safeJsonParse(stored) as DatasetValue | undefined;
    if (!parsed) {
      await adapter.setItem(key, JSON.stringify(sub.lastValue));
    }
    return parsed;
  }

  private notifyReplace(sub: SubscriptionState, value: DatasetValue) {
    sub.lastValue = value;
    sub.watchers.forEach((watcher) => {
      watcher.callback(sub.lastValue);
    });
  }

  private notifyAppend(
    sub: SubscriptionState,
    entries: ObjectWithId[],
    notifyAll = false,
  ) {
    const existing = sub.lastValue as ObjectWithId[];
    const lastKnownId = existing.reduce(
      (max, entry) => (entry.id > max ? entry.id : max),
      -1,
    );
    entries.forEach((entry) => {
      if (existing.some((existingEntry) => existingEntry.id === entry.id)) {
        return;
      }
      if (notifyAll || entry.id > lastKnownId) {
        existing.push(entry);
        sub.watchers.forEach((watcher) => {
          watcher.callback(entry);
        });
      }
    });
  }

  private async persistDatasetValue(sub: SubscriptionState): Promise<void> {
    const adapter = this.storageAdapterForDataset(sub.dataset);
    const key = storageKeyForDatasetKey(sub.datasetKey);
    await adapter.setItem(key, JSON.stringify(sub.lastValue));
  }

  private mergeReplace(sub: SubscriptionState, stored: DatasetValue) {
    const storedEpoch = stored as ObjectWithEpoch;
    const lastEpoch = sub.lastValue as ObjectWithEpoch;
    if (storedEpoch.epoch > lastEpoch.epoch) {
      this.notifyReplace(sub, storedEpoch);
    }
  }

  private mergeAppend(sub: SubscriptionState, stored: DatasetValue) {
    const entries = stored as ObjectWithId[];
    if (entries.length === 0) return;
    this.notifyAppend(sub, entries);
  }

  private async hydrateFromStorage(sub: SubscriptionState) {
    const stored = await this.loadStoredValue(sub);
    if (!stored) {
      return;
    }
    if (sub.action === "append") {
      this.mergeAppend(sub, stored);
    } else {
      this.mergeReplace(sub, stored);
    }
  }

  watch(
    dataset: Dataset,
    params: DatasetParams,
    initialValue: DatasetValue,
    onUpdate: (value: object) => void,
  ): () => void {
    const datasetKey = buildDatasetKey(dataset, params);
    let sub = this.subsByDataset.get(datasetKey);
    if (!sub) {
      const action = actionForDataset(dataset);
      const lastValue =
        action === "append"
          ? [...(initialValue as ObjectWithId[])]
          : initialValue;
      sub = {
        datasetKey,
        dataset,
        params,
        action,
        lastValue,
        initialValue:
          action === "append"
            ? [...(initialValue as ObjectWithId[])]
            : initialValue,
        watchers: [],
      };
      this.subsByDataset.set(datasetKey, sub);
      sub.loadPromise = this.hydrateFromStorage(sub);
    } else {
      if (sub.action === "append") {
        this.notifyAppend(sub, initialValue as ObjectWithId[]);
      } else {
        this.mergeReplace(sub, initialValue);
      }
    }

    const watcherId = genId();
    const watcher = { id: watcherId, callback: onUpdate };
    sub.watchers.push(watcher);

    if (sub.loadPromise) {
      void sub.loadPromise.then(() => {
        if (sub?.action === "append") {
          const entries = sub.lastValue as ObjectWithId[];
          const lastKnownId = (initialValue as ObjectWithId[]).reduce(
            (max, entry) => (entry.id > max ? entry.id : max),
            -1,
          );
          entries.forEach((entry) => {
            if (entry.id > lastKnownId) {
              watcher.callback(entry);
            }
          });
        } else if (sub?.lastValue !== initialValue) {
          watcher.callback(sub.lastValue);
        }
      });
    }

    return () => {
      const current = this.subsByDataset.get(datasetKey);
      if (!current) return;
      current.watchers = current.watchers.filter((w) => w.id !== watcherId);
    };
  }

  async replaceDataset(
    dataset: Dataset,
    params: DatasetParams,
    value: DatasetValue,
  ) {
    const datasetKey = buildDatasetKey(dataset, params);
    const existing = this.subsByDataset.get(datasetKey);
    const sub =
      existing ??
      ({
        datasetKey,
        dataset,
        params,
        action: "replace",
        lastValue: value,
        initialValue: value,
        watchers: [],
      } as SubscriptionState);
    sub.action = "replace";
    sub.initialValue = value;
    this.subsByDataset.set(datasetKey, sub);
    this.notifyReplace(sub, value);
    await this.persistDatasetValue(sub);
  }

  async appendDataset(
    dataset: Dataset,
    params: DatasetParams,
    entry: ObjectWithId,
  ) {
    const datasetKey = buildDatasetKey(dataset, params);
    const existing = this.subsByDataset.get(datasetKey);
    const sub =
      existing ??
      ({
        datasetKey,
        dataset,
        params,
        action: "append",
        lastValue: [],
        initialValue: [],
        watchers: [],
      } as SubscriptionState);
    sub.action = "append";
    this.subsByDataset.set(datasetKey, sub);
    this.notifyAppend(sub, [entry], true);
    await this.persistDatasetValue(sub);
  }

  async exportState(): Promise<LocalStateExport> {
    await this.maybeMigrate();
    const datasets: Record<string, DatasetValue> = {};
    const localKeys = await this.localStorageAdapter.keys();
    const indexedKeys = await this.indexedDbAdapter.keys();
    const allKeys = [...new Set([...localKeys, ...indexedKeys])];
    for (const key of allKeys) {
      if (!key.startsWith(STORAGE_PREFIX)) continue;
      const datasetKey = key.slice(STORAGE_PREFIX.length);
      const { dataset } = parseDatasetKey(datasetKey) ?? {};
      if (!dataset) continue;
      const adapter = this.storageAdapterForDataset(dataset);
      const raw = await adapter.getItem(key);
      const parsed = safeJsonParse(raw) as DatasetValue | undefined;
      if (parsed !== undefined) {
        datasets[datasetKey] = parsed;
      }
    }
    return {
      version: LOCAL_STATE_VERSION,
      exportedAt: new Date().toISOString(),
      datasets,
    };
  }

  async importState(
    payload: LocalStateExport,
    { reload = true }: { reload?: boolean } = {},
  ) {
    await this.clearStoredDatasets();
    await this.localStorageAdapter.setItem(
      VERSION_KEY,
      String(LOCAL_STATE_VERSION),
    );
    const entries = Object.entries(payload.datasets ?? {});
    for (const [datasetKey, value] of entries) {
      const parsed = parseDatasetKey(datasetKey);
      if (!parsed) continue;
      const adapter = this.storageAdapterForDataset(parsed.dataset);
      const key = storageKeyForDatasetKey(datasetKey);
      await adapter.setItem(key, JSON.stringify(value));
    }
    if (reload && typeof window !== "undefined") {
      window.location.reload();
    }
  }

  async reset({ reload = true }: { reload?: boolean } = {}) {
    await this.clearStoredDatasets();
    await this.localStorageAdapter.setItem(
      VERSION_KEY,
      String(LOCAL_STATE_VERSION),
    );
    if (reload && typeof window !== "undefined") {
      window.location.reload();
    }
  }
}

const localDatasetManager = new LocalDatasetManager();

export const exposeLocalStateTools = () => {
  if (typeof window === "undefined") return;
  (
    window as unknown as {
      huntLocalState?: {
        version: number;
        exportState: () => Promise<LocalStateExport>;
        importState: (
          payload: LocalStateExport,
          options?: { reload?: boolean },
        ) => Promise<void>;
        reset: (options?: { reload?: boolean }) => Promise<void>;
        replaceDataset: (
          dataset: Dataset,
          params: DatasetParams,
          value: DatasetValue,
        ) => Promise<void>;
        appendDataset: (
          dataset: Dataset,
          params: DatasetParams,
          entry: ObjectWithId,
        ) => Promise<void>;
      };
    }
  ).huntLocalState = {
    version: LOCAL_STATE_VERSION,
    exportState: () => localDatasetManager.exportState(),
    importState: (payload, options) =>
      localDatasetManager.importState(payload, options),
    reset: (options) => localDatasetManager.reset(options),
    replaceDataset: (dataset, params, value) =>
      localDatasetManager.replaceDataset(dataset, params, value),
    appendDataset: (dataset, params, entry) =>
      localDatasetManager.appendDataset(dataset, params, entry),
  };
};

export { LOCAL_STATE_VERSION, localDatasetManager, type LocalStateExport };
