import type { TeamHuntState } from "@hunt/public-client";
import { useEffect, useMemo, useState } from "react";
import {
  type DatasetParams,
  type Dataset,
  type ObjectWithEpoch,
} from "../../../lib/api/websocket";
import {
  applySolvedMapToTeamState,
  useSolvedPuzzlesState,
} from "../components/puzzleSolveLocalState";
import { IS_STATIC_SITE } from "../utils/staticSite";
import globalDatasetManager from "./DatasetManager";

function useDataset<T extends ObjectWithEpoch>(
  dataset: Dataset,
  params: DatasetParams,
  initialValue: T,
): T {
  const [state, setState] = useState<T>(initialValue);
  const { solvedMap } = useSolvedPuzzlesState();

  useEffect(() => {
    const stop = globalDatasetManager.watch(
      dataset,
      params,
      state,
      (value: object) => {
        setState(value as T);
      },
    );
    return stop;
    // eslint-disable-next-line react-hooks/exhaustive-deps -- We explicitly exclude `state` from the dependency set since we don't want to re-establish the watch on every update.
  }, [dataset, JSON.stringify(params)]);

  const mergedState = useMemo(() => {
    if (!IS_STATIC_SITE || dataset !== "team_state") {
      return state;
    }
    return applySolvedMapToTeamState(
      state as unknown as TeamHuntState,
      solvedMap,
    ) as unknown as T;
  }, [dataset, solvedMap, state]);

  return mergedState;
}

export default useDataset;
